export const YEAR_FILTERS = ['All', '2026', '2025', '2024', '2023', '2022', 'Previous'];

export const getActivityYear = (activity) => {
  const dateText = `${activity.sortDate || ''} ${activity.year || ''} ${activity.date || ''}`;
  const match = dateText.match(/(20\d{2}|19\d{2})/);
  return match ? match[1] : '';
};

export const filterByYear = (activities, year) => {
  if (year === 'All') return activities;
  if (year === 'Previous') {
    return activities.filter((activity) => {
      const activityYear = getActivityYear(activity);
      return activityYear && parseInt(activityYear, 10) < 2024;
    });
  }
  return activities.filter((activity) => getActivityYear(activity) === year);
};

export const searchActivities = (activities, query) => {
  if (!query) return activities;
  const lowerQuery = query.toLowerCase();
  return activities.filter((activity) =>
    activity.eventTitle?.toLowerCase().includes(lowerQuery) ||
    activity.organizationName?.toLowerCase().includes(lowerQuery) ||
    activity.topic?.toLowerCase().includes(lowerQuery) ||
    activity.description?.toLowerCase().includes(lowerQuery) ||
    activity.role?.toLowerCase().includes(lowerQuery) ||
    activity.tags?.some((tag) => tag.toLowerCase().includes(lowerQuery))
  );
};

export const sortByLatest = (activities) => {
  return [...activities].sort((a, b) => {
    const dateA = a.sortDate || `${getActivityYear(a) || '0000'}-01-01`;
    const dateB = b.sortDate || `${getActivityYear(b) || '0000'}-01-01`;
    return dateB.localeCompare(dateA);
  });
};

